  "decision": "accept",
  "icd10_code": "E11.22",
  "code_display": "Type 2 DM with diabetic CKD",
  "guideline_citations": [
    {
      "url": "https://www.cms.gov/files/document/fy-2027-icd-10-cm-coding-guidelines.pdf",
      "quote": "The classification presumes a causal relationship between the two conditions linked by these terms in the Alphabetic Index or Tabular List. These conditions should be coded as related even in the absence of provider documentation explicitly linking them, unless the documentation clearly states the conditions are unrelated or when another guideline exists that specifically requires a documented linkage between two conditions (e.g., sepsis guideline for “acute organ dysfunction that is not clearly associated with the sepsis”).",
      "source": "ICD-10-CM Official Guidelines for Coding and Reporting FY 2027, Section I.A.15"
    }
  ],
  "rationale": "The chart contains explicit documentation of type 2 diabetes mellitus (assessment: currently active), chronic kidney disease stage 3, and active diabetic nephropathy. The mention windows show no retractions, negations, family history, screening, hypothetical, or resolved language. The guideline excerpt supports presuming a causal relationship between diabetes and diabetic nephropathy, satisfying the combination code criteria. No medication-only or lab-only evidence is relied upon; the diagnosis is directly stated.",
  "physician_query_needed": false
}
